import json
import os
import re
import subprocess
import sys


class Report:
    def __init__(self):
        self.problems = []

    def check(self, cond, msg):
        if not cond:
            self.problems.append(msg)
        return bool(cond)

    def finish(self):
        if self.problems:
            print(f"FAIL: {len(self.problems)} problem(s)")
            for p in self.problems[:14]:
                print("  - " + p)
            if len(self.problems) > 14:
                print(f"  ... and {len(self.problems) - 14} more")
            sys.exit(1)
        print("ok")


def die(msg):
    print("FAIL: " + msg)
    sys.exit(1)


def read(path):
    try:
        with open(path, encoding="utf-8") as f:
